import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{t}from"./archive-BN_dSUo6.js";import{A as n,C as r,E as i,M as a,N as o,O as s,P as c,S as l,c as u,k as d,l as f,n as p,o as m,p as h,t as g,v as _}from"./shared-BLp3PbbW.js";import{t as v}from"./database-B9dOoFl-.js";import{t as y}from"./search-BkIlyY7f.js";import{t as b}from"./shield-check-DLlmt4Nd.js";import{t as x}from"./CodeEditor-DqHMt3P8.js";var S=e(),C=`Этап 4 · Блок 15 · Полный SQL-путь и единое переключение`;function w({module:e}){return(0,S.jsxs)(o,{children:[(0,S.jsx)(a,{variant:`project`,chip:e??C,title:`Убираем JSON-backend`,intro:`После перехода обоих интерфейсов на SQLite уберём старый файловый путь и проверим, что Planner больше от него не зависит.`,tags:[{icon:(0,S.jsx)(y,{size:14}),label:`граф зависимостей`},{icon:(0,S.jsx)(v,{size:14}),label:`один SQL-путь`},{icon:(0,S.jsx)(b,{size:14}),label:`без fallback`},{icon:(0,S.jsx)(t,{size:14}),label:`импорт остаётся`}]}),(0,S.jsxs)(c,{number:`00`,title:`От переключения к чистому SQL-пути`,children:[(0,S.jsx)(s,{children:`Предыдущее занятие переносит актуальные задачи и направляет API и CLI к одной SQLite-базе. Но старые классы, настройки и тестовые фикстуры могут всё ещё ссылаться на JSON-хранилище. Теперь мы проследим эти ссылки и удалим переходный backend только после проверки его потребителей.`}),(0,S.jsx)(d,{variant:`connected`,items:[{title:`Точка старта`,description:`Ожидаемый вход по концепту: B75 подтверждена, API и CLI используют общую SQLite, а JSON больше не меняется штатными операциями.`},{title:`Новый вопрос`,description:`Какие старые файлы и ветки ещё удерживают зависимость от файлового Planner, а какие упоминания JSON нужны по другим причинам?`},{title:`Результат`,description:`Рабочий SQL-путь сохраняет прежние возможности, старое файловое хранилище удалено, отдельный перенос и нужный JSON-формат сохранены.`}]}),(0,S.jsx)(`p`,{children:`Сначала мы сверим фактическое состояние проекта с результатом переключения, затем разберём граф зависимостей, перенесём проверки на SQL и проверим независимость в новом запуске. Сам номер занятия и наличие SQL-классов не доказывают, что обе сборки действительно прошли через SQLite. Если входное состояние не совпадает с B75, удалять JSON-путь пока рано.`})]}),(0,S.jsxs)(c,{number:`01`,title:`Удаляем переход только после подтверждённого переключения`,children:[(0,S.jsx)(s,{children:`Переход на новый источник и удаление прежнего кода решают разные задачи. Сначала мы подтверждаем, что API и CLI работают через SQLite, затем проверяем, что именно ещё зависит от файлового backend.`}),(0,S.jsx)(`p`,{children:`Представим вокзал, где пассажиров уже перенаправили на новую платформу. Старую кассу можно закрыть лишь после того, как проверили все маршруты, табло и служебные окна, которые к ней обращались. В проекте пассажирами будут runtime-пути, а указателями на кассу станут импорты, вызовы фабрик, настройки и тестовые фикстуры. Граница аналогии в том, что кодовую зависимость мы подтверждаем поиском и поведением тестов, а не наблюдением за пассажиропотоком.`}),(0,S.jsx)(`p`,{children:`Проверка входа смотрит на оба интерфейса и на один адрес базы: API создаёт запись, CLI её находит, изменение через CLI видно новому API-запросу, а состояние переживает новый запуск. Дополнительно подтверждаем, что финальный снимок был перенесён и JSON-файл больше не обновляется обычной работой. Одна удачная команда или зелёный unit-тест этого не доказывает.`}),(0,S.jsx)(i,{tone:`warn`,children:`Если подтверждён только промежуточный SQL-репозиторий или результат репетиции импорта, мы останавливаем очистку. Сначала нужен фактический B75; изменения в незавершённой рабочей копии не заменяют проверку штатного поведения.`}),(0,S.jsx)(`p`,{children:`В маленькой независимой карте ниже три потребителя пока не все переведены. Проследим, как меняется решение об удалении backend после переноса последнего тестового потребителя.`}),(0,S.jsx)(_,{code:`consumers = {"api": "sql", "cli": "sql", "tests": "json"}
all_on_sql = all(source == "sql" for source in consumers.values())
print(all_on_sql)
consumers["tests"] = "sql"
all_on_sql = all(source == "sql" for source in consumers.values())
print(all_on_sql)`,steps:[{line:0,note:`Это учебная карта ролей, не исходный код проекта. API и CLI уже указывают на SQL, но тесты ещё держат файловый путь.`,vars:{consumers:`api и cli: sql; tests: json`}},{line:1,note:`all проверяет все значения. Одного оставшегося потребителя достаточно, чтобы условие удаления не прошло.`,vars:{all_on_sql:`False`}},{line:2,note:`Первый вывод показывает, что старый backend ещё нужен хотя бы тестовой части.`,vars:{output:`False`}},{line:3,note:`После перевода фикстур на SQL-контекст файловый backend больше не является их зависимостью.`,vars:{tests:`sql`}},{line:4,note:`Теперь проверка учитывает все три потребителя и возвращает True.`,vars:{all_on_sql:`True`}},{line:5,note:`Второй вывод разрешает перейти к удалению. В реальном проекте аналогичную карту подтверждаем поиском и тестами.`,vars:{output:`True`}}]}),(0,S.jsx)(x,{caption:`Вывод независимого примера`,code:`False
True`}),(0,S.jsx)(`p`,{children:`Порядок зависимостей важен: переносим потребителя, проверяем его, затем удаляем поставщика старой реализации. Если удалить класс раньше, импорт упадёт; если оставить скрытую ветку на случай сбоя, приложение сохранит два источника данных.`})]}),(0,S.jsxs)(c,{number:`02`,title:`JSON может быть форматом, а не хранилищем`,children:[(0,S.jsx)(s,{children:`Поиск слова JSON покажет разные части системы. Мы определяем роль по тому, кто читает данные, кто их записывает и когда.`}),(0,S.jsx)(`p`,{children:`JSON как формат похож на конверт: он задаёт способ упаковать и прочитать значения, но не говорит, в каком месте они будут храниться и сколько живут. Один и тот же набор полей может уйти в HTTP-ответ, оказаться в колонке SQLite, быть сохранён копией файла или прочитан отдельным импортёром. Граница аналогии: конверт не описывает правила транзакции и не выбирает источник истины; это определяют участники и путь данных.`}),(0,S.jsx)(n,{rows:[[`JsonStorage`,`Старый runtime-backend читает и перезаписывает файл задач. После B75 его потребители удаляются.`],[`HTTP JSON`,`Формат публичного тела ответа и запроса. Он остаётся частью API-контракта.`],[`TaskRow.tags`,`Значение хранится в JSON-колонке SQLite. Это не файловый backend и не повод удалять поле.`],[`import_tasks.py`,`Отдельно читает явно выбранную копию снимка и переносит её в пустую цель.`],[`Архивный файл`,`Сохраняет состояние до переключения и не участвует в штатном чтении или записи Planner.`]]}),(0,S.jsx)(`p`,{children:`Сопоставим название с назначением. Это помогает не удалить рабочий HTTP-контракт, внутренние tags или импорт исторических записей вместе с ненужным файловым backend.`}),(0,S.jsx)(h,{prompt:`Сопоставим объект с его ролью после перехода на SQLite.`,leftTitle:`Объект`,rightTitle:`Роль`,pairs:[{left:`app/storage.py`,right:`Старый файловый runtime`},{left:`HTTP JSON`,right:`Публичная сериализация API`},{left:`TaskRow.tags`,right:`JSON-колонка SQLite`},{left:`import_tasks.py`,right:`Явный инструмент переноса`},{left:`копия tasks.json`,right:`Архивный снимок`}],explanation:`Совпадение формата не означает совпадение жизненного цикла: удаляем runtime-хранилище, а остальные роли оцениваем отдельно.`}),(0,S.jsx)(`p`,{children:`Также отделим общую сериализацию предметной Task от JsonStorage. Метод преобразования модели может быть нужен импортёру, даже когда класс, который читает и записывает рабочий файл, уже не нужен. Мы сохраняем каждую функцию, у которой остаётся конкретный потребитель, и убираем только ссылку на старый источник.`})]}),(0,S.jsxs)(c,{number:`03`,title:`Убираем старые ссылки по графу использования`,children:[(0,S.jsx)(s,{children:`Backend не заканчивается на классе, который открывает JSON-файл. Его путь может начинаться в конфигурации и проходить через фабрику к сервису.`}),(0,S.jsx)(`p`,{children:`В проекте проследим связи от точки запуска до репозитория. Проверим API provider и CLI-сборку, build_service, параметр storage, JsonTaskRepository, JsonStorage и MemoryStorage, путь JSON_PATH, импорты в тестах и примеры запуска. Потребитель важнее имени файла: если удаляемый класс вызывается только тестом, эта фикстура всё ещё должна быть переписана, но рабочая сборка при этом может уже не зависеть от него.`}),(0,S.jsx)(`p`,{children:`Ниже показан ожидаемый путь после очистки. API и CLI используют одну настройку и общую фабрику, однако получают отдельную короткую Session на запрос или команду. Они проходят через прикладной сервис к SQL-репозиторию. Импортёр стоит отдельно: ему передаются конкретные источник и цель, поэтому он не должен создавать скрытую зависимость от app/storage.py.`}),(0,S.jsxs)(g,{caption:`Обычная работа Planner и отдельный перенос`,orientation:`vertical`,children:[(0,S.jsx)(u,{title:`Штатный API и CLI`,children:(0,S.jsxs)(m,{label:`Путь штатной операции Planner`,orientation:`vertical`,children:[(0,S.jsx)(f,{title:`API и CLI: точки входа`,children:(0,S.jsx)(`p`,{children:`Каждый интерфейс создаёт свою короткую Session`})}),(0,S.jsx)(p,{label:`получает SQL-сервис`}),(0,S.jsx)(f,{title:`PlannerService`,children:(0,S.jsx)(`p`,{children:`Сохраняет предметные правила`})}),(0,S.jsx)(p,{label:`вызывает операции`}),(0,S.jsx)(f,{title:`SqlTaskRepository и Session`,children:(0,S.jsx)(`p`,{children:`Читают или меняют выбранные строки`})}),(0,S.jsx)(p,{label:`подтверждённые данные`}),(0,S.jsx)(f,{title:`SQLite`,shape:`database`,children:(0,S.jsx)(`p`,{children:`Единственный рабочий источник`})})]})}),(0,S.jsx)(u,{title:`Разовый перенос исторических данных`,children:(0,S.jsxs)(m,{label:`Изолированный путь импортёра`,orientation:`vertical`,children:[(0,S.jsx)(f,{title:`Архивная копия JSON`,children:(0,S.jsx)(`p`,{children:`Источник для разового импорта, не для runtime`})}),(0,S.jsx)(p,{label:`проверяет и переносит`}),(0,S.jsx)(f,{title:`import_tasks.py`,children:(0,S.jsx)(`p`,{children:`Запускается отдельно с заданными адресами`})}),(0,S.jsx)(p,{label:`одна транзакция`}),(0,S.jsx)(f,{title:`Пустая целевая SQLite`,shape:`database`,children:(0,S.jsx)(`p`,{children:`Содержимое сверяется новой Session`})})]})})]}),(0,S.jsx)(`p`,{children:`В обеих дорожках есть SQLite, но это не превращает импортёр во второй runtime. Штатный Planner получает данные через свой сервис при обычном запросе. Импортёр выполняет отдельную административную команду для заранее выбранной копии. После завершения урока приложение не опрашивает архив и не переключается на него при сбое базы.`}),(0,S.jsx)(`p`,{children:`Порядок правок следует связям: сначала переводим оставшийся потребитель на SQL, потом удаляем старый параметр или класс, после этого убираем настройку, которой больше никто не пользуется. Ошибка импорта не должна маскироваться try/except или временной заглушкой. Если ссылка нужна сериализатору либо импортёру, её оставляем и проверяем отдельно.`})]}),(0,S.jsxs)(c,{number:`04`,title:`Тесты сохраняют договор, а не старый счётчик`,children:[(0,S.jsx)(s,{children:`После удаления backend тесты по-прежнему должны подтверждать поведение Planner. Но проверка внутреннего save-count больше не описывает продуктовую гарантию.`}),(0,S.jsx)(`p`,{children:`Например, тест создания важен не потому, что конкретный метод save вызвался ровно один раз. Важно, что HTTP-операция возвращает прежний статус и задача доступна через новый запрос или новую Session. Фикстура базы должна быть отдельной для теста; тестовый SQL-сервис не хранит общую Session в app.state и не касается рабочей базы.`}),(0,S.jsx)(`p`,{children:`Сравним две проверки одного сценария. Первая привязана к прежней реализации хранения. Вторая проверяет сохранённый результат через интерфейс продукта и независимое чтение. Нам нужна вторая гарантия, а отдельные тесты методов SQL-репозитория продолжают проверять его собственный контракт.`}),(0,S.jsx)(l,{statement:`Успешный HTTP-ответ после создания сам по себе доказывает, что новая Session прочитает сохранённую задачу из SQLite.`,isTrue:!1,explanation:`Ответ может быть собран из объекта в памяти. Мы подтверждаем сохранение отдельным чтением через новый ресурс и проверяем публичный договор отдельно от деталей JsonStorage.`}),(0,S.jsx)(`p`,{children:`Тесты, которые проверяют только файловый backend, можно убрать или заменить проверками исходного формата в тестах импортёра. Остальные service, API и CLI фикстуры переводятся на временную SQLite. Так мы не повторяем всю разработку CRUD: сохраняем уже пройденные гарантии и меняем только способ изоляции и чтения результата.`}),(0,S.jsx)(`p`,{children:`Существующие правила остаются прежними: внутренние tags не теряются, PUT и PATCH сохраняют свою семантику, поиск и статистика дают знакомый результат, ошибки неизвестной задачи не превращаются в пустой список. В этой теме мы не меняем HTTP-схемы или маршруты ради новой базы.`})]}),(0,S.jsxs)(c,{number:`05`,title:`Ошибка базы не включает старый источник`,children:[(0,S.jsx)(s,{children:`Когда SQLite недоступна, приложение должно сообщить об отказе через уже заданную границу. Оно не должно молча выдавать устаревшие данные из файла или временной памяти.`}),(0,S.jsx)(`p`,{children:`Fallback, то есть незаметный запасной путь, кажется удобным: приложение продолжает отвечать. Но если API прочитает одну задачу из SQLite, а затем при ошибке возьмёт список из JSON, ответ может соединить два разных состояния. Запись тоже может выглядеть успешной, хотя SQLite её не приняла. Поэтому два backend-а не являются взаимозаменяемыми резервами после первой SQL-записи.`}),(0,S.jsx)(`p`,{children:`Изолированная проверка намеренно направляет соединение к недоступной тестовой базе. Мы ожидаем, что операция завершится ошибкой, ресурс освободится, а приложение не создаст новый tasks.json и не вернёт ответ из MemoryStorage. Проверяем это в новом процессе, чтобы старая Session или объект сервиса не прятали неправильную сборку.`}),(0,S.jsx)(`p`,{children:`Отдельный процесс запускает новый интерпретатор Python. Аргумент env в subprocess.run передаёт ему копию окружения, то есть набора строковых настроек процесса. Задав там DATABASE_URL до импорта app.api, мы направляем дочернее приложение на тестовый адрес. Для SQLite возьмём путь внутри отсутствующего родительского каталога: Engine соберётся, но первое подключение не сможет открыть файл. Так мы проверяем отказ соединения, а не придумываем новый HTTP-статус.`}),(0,S.jsx)(x,{caption:`Фрагмент: передаём тестовый адрес отдельному процессу`,code:`import os
import subprocess
import sys

environment = os.environ.copy()
environment["DATABASE_URL"] = database_url
subprocess.run(
    [sys.executable, "-c", child_code],
    env=environment,
    check=True,
)`}),(0,S.jsx)(`p`,{children:`Новый процесс похож на второе окно терминала: объекты Session из памяти родителя в нём не существуют. Через env мы передаём только нужные настройки, а файлы остаются общими, поэтому контрольный JSON и SQLite лежат в tmp_path. TestClient отправляет запрос приложению внутри дочернего процесса, сервер отдельно запускать не нужно. TrackingSession наследует Session и переопределяет close(): отмечает вызов, затем вызывает super().close(), чтобы настоящее закрытие сохранилось.`}),(0,S.jsx)(`p`,{children:`OperationalError здесь означает, что SQLAlchemy не смог открыть соединение с SQLite. TestClient по умолчанию пробрасывает исключение приложения, поэтому мы ловим именно отказ подключения и не сравниваем HTTP-статус. Если изменить настройку raise_server_exceptions, тест начал бы проверять сформированный ответ, но это уже другая граница.`}),(0,S.jsx)(`p`,{children:`До запуска дочернего процесса сохраняем байты контрольного JSON. Если API вернёт его содержимое вместо ошибки, проверка ожидаемого исключения завершится неудачей; если файл изменится, сравнение байтов в родительском процессе это обнаружит. Так мы отдельно видим ложный успех и побочную запись.`}),(0,S.jsx)(l,{statement:`Если задать DATABASE_URL после импорта app.api, уже созданный Engine автоматически переключится на новый файл.`,isTrue:!1,explanation:`app.api создаёт Engine при импорте, поэтому новое окружение передаётся процессу до запуска кода. Сначала subprocess.run получает DATABASE_URL через env, затем child_code импортирует приложение.`}),(0,S.jsx)(r,{code:`# Фрагмент функции с подозрительной веткой fallback
def list_tasks(service):
    try:
        return service.list_tasks()
    except Exception:
        return JsonStorage(JSON_PATH).load()`,question:`Почему эта ветка нарушает результат перехода на SQLite?`,options:[`Она обращается к старому файлу при любом исключении и может вернуть устаревший снимок как текущие данные.`,`Она вызывает list_tasks до создания HTTP-ответа, а это всегда запрещено.`,`Она не преобразует список задач в JSON-строку вручную.`],correctIndex:0,explanation:`Перехватывается любое исключение, после чего включается второй источник истины. Отказ базы становится похож на успешное чтение старого состояния.`,fix:`def list_tasks(service):
    return service.list_tasks()`}),(0,S.jsx)(`p`,{children:`В целевом проекте мы удаляем ветку fallback и используем существующее поведение ошибки для API или CLI. Здесь не требуется новое обещание HTTP 503 или полная классификация исключений: такие границы разбираются дальше. Но ложный успех и возврат к файлу запрещены уже сейчас. Rollback отменяет незавершённые изменения транзакции, он не отменяет commit, который уже подтвердил операция.`}),(0,S.jsx)(i,{tone:`info`,children:`Проверку отказа выполняем только на временной базе и тестовых данных. Мы не удаляем рабочую базу или резервную копию, чтобы искусственно вызвать ошибку.`})]}),(0,S.jsxs)(c,{number:`06`,title:`Импортёр и архив остаются вне runtime`,children:[(0,S.jsx)(s,{children:`Очистка завершена только тогда, когда старый рабочий путь удалён, а нужные инструменты переноса продолжают жить независимо от него.`}),(0,S.jsx)(`p`,{children:`Импортёр сохраняет историческую полезность, но не запускается при импорте приложения и не исполняется при каждом открытии Session. Его команда явно получает снимок и адрес цели; проверяет вход; требует подготовленную пустую таблицу; записывает полный набор одной транзакцией. Проверки старого JSON-формата теперь принадлежат этой команде, а не тестам JsonStorage.`}),(0,S.jsx)(`p`,{children:`Архивная копия нужна для сохранения исходного состояния до переключения. После появления новых SQL-записей она уже не является актуальным рабочим источником и её нельзя просто выбрать обратно. Удаление JSON_PATH из настроек не удаляет архивный файл и не меняет HTTP-ответы. В настройках приложения остаётся DATABASE_URL, а APP_NAME и COOKIE_SECURE сохраняют свои отдельные роли.`}),(0,S.jsx)(`p`,{children:`Минимальные примеры запуска или .env.example меняем только там, где они всё ещё предлагают файловый backend. Полный README, воспроизводимую установку с чистого checkout и общий аудит ошибок здесь не переделываем. Завершаем занятием, в котором следующий блок получает готовый DB Planner для более глубокого разбора отказов и SQL-запросов.`})]}),(0,S.jsxs)(c,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,S.jsx)(s,{children:`Работаем с существующим StudyHub после подтверждённого переключения. Сначала выясним, какие ссылки принадлежат runtime, тестам, импорту и архиву; затем удалим только старый backend и проверим продукт на временной базе.`}),(0,S.jsx)(d,{variant:`connected`,items:[{title:`Проверим вход и потребителей`,description:`Подтвердим B75 фактическим поведением API и CLI, затем разделим ссылки на runtime, тесты, JSON-формат, импортёр и архив.`},{title:`Уберём старый runtime`,description:`Перенесём оставшиеся сборки и настройки на SQL, обновим зависимые fixtures и удалим JsonTaskRepository, старые storage-классы и JSON_PATH.`},{title:`Докажем независимость`,description:`В новом процессе проверим прежние API и CLI-возможности на отдельной SQLite, отказ без fallback и независимый импорт копии.`}]}),(0,S.jsx)(`p`,{children:`Входом служат сохранённые правила продукта и работающий SQL-путь, а не новая реализация Planner. Каждое удаление опирается на найденного потребителя: сначала его переводим и проверяем, потом убираем старую зависимость. В конце проверяем знакомые операции и сохраняем импортёр в отдельной роли.`}),(0,S.jsx)(`p`,{children:`Если фактическая версия StudyHub ещё не достигает B75, мы останавливаем именно зависимую очистку и фиксируем, какой сценарий переключения отсутствует. Работа на этой версии не должна создавать видимость завершённого SQL-продукта. После подтверждённого B75 итогом становятся один runtime-источник, прежний пользовательский договор и безопасный отказ без скрытого возврата к JSON.`})]})]})}export{w as Lesson75_1};